<script lang="ts">import {page} from '$app/stores';import {goto} from '$app/navigation';import Icon from '$lib/components/Icon.svelte';import Compose from '$lib/components/mail/Compose.svelte';import {mailState,mailReady,mailStorageError,mailCommand} from '$lib/mail/store';import {address,messagesFor,visibleMessages,type Folder,type Message,type Command} from '$lib/mail/model.js';
 const folderNames:['Inbox','Starred','Sent','Drafts','Archive','Spam','Trash']=['Inbox','Starred','Sent','Drafts','Archive','Spam','Trash'];
 const icons=['Email','Star','External','File','Storage','Certificates','Trash'];let folder:Folder|'Starred'='Inbox',query='',selected='',reader=false,error='',notice='',compose:false|{mode:'new'|'reply'|'forward'|'draft';original?:Message}=false;
 $: mailbox=$mailState.mailboxes.find(m=>m.id===$page.params.id);$: messages=mailbox?messagesFor($mailState,mailbox.id):[];$: list=visibleMessages(messages,folder,query);$: active=list.find(x=>x.id===selected);$: if(!mailbox||mailbox.suspended)compose=false;
 function run(c:Command){try{mailCommand(c);error='';return true;}catch(e){error=e instanceof Error?e.message:'Mail action failed.';return false;}}
 function selectFolder(f:Folder|'Starred'){folder=f;selected='';reader=false;query='';notice='';}
 function open(x:Message){if(!mailbox)return;selected=x.id;reader=true;if(!x.read)run({type:'read',mailbox:mailbox.id,id:x.id,value:true});}
 function move(x:Message,f:Folder){if(mailbox&&run({type:'move',mailbox:mailbox.id,id:x.id,folder:f})){selected='';reader=false;}}
 function restore(x:Message){if(mailbox&&run({type:'restore',mailbox:mailbox.id,id:x.id})){selected='';reader=false;}}
 function remove(x:Message){if(mailbox&&window.confirm('Delete this sample message forever?')&&run({type:'delete-message',mailbox:mailbox.id,id:x.id})){selected='';reader=false;}}
 function switchMailbox(id:string){if(compose&&!window.confirm('Discard the unsaved message?'))return;compose=false;selectFolder('Inbox');error='';void goto('/webmail/'+encodeURIComponent(id));}
 const date=(d:string)=>new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric'});
</script>
<svelte:head><title>{mailbox?address(mailbox)+' · Drevanta Webmail':'Drevanta Webmail'}</title></svelte:head>
<div class="native-webmail"><header class="wm-header"><div class="wm-brand"><span class="brand-mark" aria-hidden="true">▦</span><span>dre<span class="brand-accent">vanta</span> <small>Webmail</small></span></div><div class="wm-head-right"><span class="wm-demo">Local demo · no mail sent</span>{#if mailbox}<label class="field mail-switch"><span class="visually-hidden">Switch mailbox (demo only)</span><select aria-label="Switch sample mailbox" value={mailbox.id} on:change={(e)=>switchMailbox(e.currentTarget.value)}>{#each $mailState.mailboxes as m}<option value={m.id}>{address(m)}</option>{/each}</select></label>{/if}</div></header>{#if !$mailReady}<p class="native-wm-notice">Loading mailbox…</p>{:else if $mailStorageError}<p class="native-wm-notice" role="alert">{$mailStorageError}</p>{:else if !mailbox||mailbox.suspended}<section class="card wm-unavailable"><h3>{mailbox?'Mailbox suspended':'Mailbox unavailable'}</h3><p class="subtitle">Enable or create this sample mailbox in the administration portal.</p></section>{:else}<div class="native-wm-notice" aria-live="polite">{#if error}<p class="error" role="alert">{error}</p>{:else if notice}<p class="subtitle">{notice}</p>{/if}</div><div class="mail-shell" class:mail-show-reader={reader&&!!active}><aside class="mail-folders"><button class="btn primary" on:click={()=>compose={mode:'new'}}><Icon name="Plus"/>Compose</button>{#each folderNames as f,i}<button class="mail-folder" class:active={folder===f} on:click={()=>selectFolder(f)}><Icon name={icons[i]}/><span>{f}</span>{#if f==='Inbox'}<small>{messages.filter(x=>x.folder==='Inbox'&&!x.read).length||''}</small>{/if}</button>{/each}<div class="mail-folder-foot"><small>Local demo · no mail is sent</small></div></aside><section class="mail-list" aria-label="Messages"><div class="mail-list-head"><div class="row between"><h3>{folder}</h3><small>{list.length} messages</small></div><label class="search"><Icon name="Search"/><input bind:value={query} placeholder="Search mail" aria-label="Search mail" on:input={()=>{selected='';reader=false;}}/></label></div>{#each list as x (x.id)}<div class="mail-item" class:selected={selected===x.id} class:unread={!x.read}><button class="mail-item-open" on:click={()=>open(x)}><div class="row between"><span class="mail-item-sender">{['Sent','Drafts'].includes(x.folder)?'To: '+x.to:x.from}</span><small>{date(x.date)}</small></div><strong>{x.subject||'(No subject)'}</strong><small class="mail-snippet">{x.body.replace(/\s+/g,' ').slice(0,110)}</small></button><button class="icon-btn mail-star" class:starred={x.star} aria-label={x.star?'Unstar message':'Star message'} on:click={()=>{if(mailbox)run({type:'star',mailbox:mailbox.id,id:x.id,value:!x.star});}}>{x.star?'★':'☆'}</button></div>{:else}<div class="empty-state"><h3>No messages</h3><p>This folder is empty or no messages match your search.</p></div>{/each}</section><article class="mail-reader" aria-label="Message reader">{#if active}<div class="mail-reader-inner"><div class="mail-reader-actions row wrap"><button class="btn secondary small native-reader-back" on:click={()=>{reader=false;selected='';}}>Back</button>{#if active.folder==='Drafts'}<button class="btn secondary small" on:click={()=>compose={mode:'draft',original:active}}>Edit draft</button>{/if}<button class="btn secondary small" on:click={()=>{if(mailbox&&active)run({type:'read',mailbox:mailbox.id,id:active.id,value:!active.read});}}>{active.read?'Mark unread':'Mark read'}</button>{#if active.folder==='Trash'}<button class="btn secondary small" on:click={()=>{if(active)restore(active);}}>Restore</button><button class="btn danger small" on:click={()=>{if(active)remove(active);}}>Delete forever</button>{:else}<button class="btn secondary small" on:click={()=>{if(active)move(active,'Trash');}}>Trash</button>{#if active.folder!=='Drafts'}<button class="btn secondary small" on:click={()=>{if(active)move(active,active.folder==='Archive'?'Inbox':'Archive');}}>{active.folder==='Archive'?'Move to inbox':'Archive'}</button><button class="btn secondary small" on:click={()=>{if(active)move(active,active.folder==='Spam'?'Inbox':'Spam');}}>{active.folder==='Spam'?'Not spam':'Spam'}</button>{/if}{/if}</div><h2>{active.subject||'(No subject)'}</h2><div class="row mail-sender"><span class="mail-avatar">{(active.from||'?').slice(0,1).toUpperCase()}</span><div class="grow"><strong>{active.from}</strong><small class="mail-address">{active.address}</small><small class="mail-address">To: {active.to}</small></div><small>{date(active.date)}</small></div><div class="mail-body-text">{active.body}</div>{#if active.folder!=='Drafts'&&active.folder!=='Trash'}<div class="row wrap"><button class="btn secondary" on:click={()=>compose={mode:'reply',original:active}}>Reply</button><button class="btn secondary" on:click={()=>compose={mode:'forward',original:active}}>Forward</button></div>{/if}</div>{:else}<div class="mail-reader-empty"><span class="icon-box"><Icon name="Email"/></span><h3>Select a message</h3><p class="subtitle">Read and reply to your mail here.</p></div>{/if}</article></div>{#if compose}<Compose {mailbox} mode={compose.mode} original={compose.original} onClose={()=>{if(window.confirm('Discard unsaved changes?'))compose=false;}} onSaved={(intent)=>{compose=false;selectFolder(intent==='draft'?'Drafts':'Sent');notice=intent==='draft'?'Draft saved.':'Sample message added to Sent. No email was delivered.';}}/>{/if}{/if}</div>
